import React, { useEffect, useState } from "react";
import { Link } from "react-router-dom";
import { LogOut, Package } from "lucide-react";
import { useAuth, useTheme } from "./contexts";
import { apiFetch } from "./api";
import { DeliveryLive } from "./DeliveryLive";
import { ThemeToggleButton } from "./ui";

export default function RiderDashboard() {
  const { accessToken, user, logout } = useAuth();
  const { dark, toggle } = useTheme();
  const [assignments, setAssignments] = useState([]);
  const [err, setErr] = useState("");
  const [selOrderId, setSelOrderId] = useState("");

  useEffect(() => {
    if (!accessToken) return undefined;
    let cancelled = false;
    setErr("");
    apiFetch("/api/deliveries/rider/assignments", {
      headers: { Authorization: `Bearer ${accessToken}` }
    })
      .then((d) => {
        if (cancelled) return;
        const list = Array.isArray(d.assignments) ? d.assignments : [];
        setAssignments(list);
        setSelOrderId((prev) => {
          if (prev && list.some((x) => x.orderId === prev)) return prev;
          return list[0]?.orderId || "";
        });
      })
      .catch((ex) => {
        if (!cancelled) setErr(ex?.message || "Could not load assignments");
      });
    return () => {
      cancelled = true;
    };
  }, [accessToken]);

  const onLogout = async () => {
    try {
      await logout();
    } catch {
      /* ignore */
    }
  };

  const display = String(user?.displayName || "").trim() || user?.email?.split("@")[0] || "Courier";

  return (
    <div className="min-h-screen bg-night-950 px-4 py-8 pb-24 text-slate-200">
      <div className="mx-auto flex max-w-4xl flex-col gap-8">
        <header className="flex flex-wrap items-center justify-between gap-4 border-b border-white/10 pb-6">
          <div className="flex items-center gap-3">
            <div className="flex h-10 w-10 items-center justify-center rounded-xl bg-sky-600 shadow-lg shadow-sky-900/40">
              <Package className="h-6 w-6 text-white" aria-hidden />
            </div>
            <div>
              <p className="text-[10px] font-bold uppercase tracking-wider text-slate-500">Campus Mart</p>
              <h1 className="text-xl font-semibold text-white">{display}</h1>
              <p className="text-xs text-slate-400">Courier workspace · Live map &amp; handoff controls</p>
            </div>
          </div>
          <div className="flex flex-wrap items-center gap-2">
            <ThemeToggleButton dark={dark} onToggle={toggle} />
            <Link
              className="inline-flex rounded-lg border border-white/15 bg-white/5 px-4 py-2 text-sm font-semibold text-sky-300 transition hover:bg-white/10"
              to="/"
            >
              Shop
            </Link>
            <button
              type="button"
              className="inline-flex items-center gap-1 rounded-lg border border-white/15 bg-night-900 px-4 py-2 text-sm font-semibold text-slate-300 hover:bg-night-900/80"
              onClick={() => onLogout()}
            >
              <LogOut className="h-4 w-4 shrink-0" aria-hidden /> Sign out
            </button>
          </div>
        </header>

        {err ? (
          <p className="rounded-lg border border-amber-500/35 bg-amber-500/15 px-4 py-3 text-sm text-amber-100">{err}</p>
        ) : null}

        {!err && assignments.length === 0 ? (
          <p className="text-sm text-slate-400">
            No active courier assignments yet. Sellers or admins attach you to orders from their dashboards using your user ID — then reload
            this page.
          </p>
        ) : null}

        {assignments.length > 0 ? (
          <div className="space-y-4">
            <div className="flex flex-wrap gap-2">
              {assignments.map((a) => (
                <button
                  key={a.orderId}
                  type="button"
                  onClick={() => setSelOrderId(a.orderId)}
                  className={`rounded-full px-4 py-1.5 text-xs font-semibold transition ${
                    selOrderId === a.orderId
                      ? "bg-sky-600 text-white"
                      : "border border-white/15 bg-night-900 text-slate-300 hover:bg-night-900/80"
                  }`}
                >
                  #{String(a.orderId).slice(-8)} · {(a.orderStatus || "").replace(/_/g, " ")}
                </button>
              ))}
            </div>

            {selOrderId ? (
              <div className="rounded-2xl border border-white/10 bg-white/5 p-4 dark:bg-night-900/50">
                <DeliveryLive mode="rider" accessToken={accessToken} orderId={selOrderId} />
              </div>
            ) : null}
          </div>
        ) : null}
      </div>
    </div>
  );
}
